pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockTimestamp, uint256 blockNumber) public {
        // Preserve admissible domain: pastBlockTime starts at 0, so any timestamp >= 0 is admissible;
        // block.timestamp manipulated via vm.warp; block.number via vm.roll.
        vm.assume(blockTimestamp < type(uint256).max);
        // Ensure we can send the required 10 ether to the contract.
        address caller = address(0x1234);
        vm.deal(caller, 10 ether);
        // Setup block environment with fuzzed values.
        vm.warp(blockTimestamp);
        vm.roll(blockNumber);
        // Perform the fallback call with exact 10 ether.
        vm.prank(caller);
        c.f{value: 10 ether}();
        // The general rule: pastBlockTime must be strictly greater than the block.timestamp at the time of the call
        // (since it is set to block.timestamp + 1 and require(block.timestamp > pastBlockTime) ensures it cannot equal).
        // In the mutant, if block.timestamp == pastBlockTime (initially 0 when blockTimestamp == 0),
        // the require passes and pastBlockTime becomes 1, violating the strict > property.
        assertTrue(c.pastBlockTime() > blockTimestamp);
    }
}

