pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockTs, address sender) public {
        // Keep block.timestamp within a reasonable range
        vm.assume(blockTs > 0 && blockTs < 1e15);
        // Sender must be distinct and capable of paying 10 ether
        vm.assume(sender != address(0) && sender != address(this));

        uint256 value = 10 ether;
        vm.deal(sender, value * 2);

        // Advance blockchain to the fuzzed timestamp once
        vm.warp(blockTs);

        // First admissible fallback call: must succeed (subject to other constraints)
        vm.prank(sender);
        (bool ok1,) = address(c).call{value: value}("");
        // If the first call reverted for a reason other than timestamp (e.g., block.number % 15 == 0 causing reentrancy/gas),
        // we cannot guarantee the second call will revert; skip these cases to keep assumption wide.
        if (!ok1) {
            return;
        }

        // Ensure we stay in the same block.timestamp
        vm.warp(blockTs);

        // Second call with same block.timestamp: reference must revert, mutant allows success
        vm.prank(sender);
        (bool ok2,) = address(c).call{value: value}("");

        // General rule: a second fallback call in the exact same block.timestamp must revert
        assertTrue(!ok2, "Second call in same block.timestamp should revert");
    }
}

