pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 warpTo, uint256 prevPast) public {
        // 1. (optional) vm.assume(...) / bound(...) to keep params in the ADMISSIBLE domain (keep it WIDE)
        vm.assume(prevPast < type(uint256).max);
        // Simulate previous state where pastBlockTime was set to prevPast
        // We use vm.store to set the state directly, but since vm.store is forbidden, we will use a different approach.
        // Instead, we'll make two calls: first call sets pastBlockTime to block.timestamp + 1, then we warp to a timestamp
        // that could equal the new pastBlockTime according to the mutant's logic.
        // Actually, we can just deploy a fresh contract and make a single call with a specific block.timestamp.
        // Since pastBlockTime starts at 0, block.timestamp > 0 always true.
        // To trigger the bug, we need pastBlockTime to be non-zero.
        // We'll achieve this by making an initial call to set pastBlockTime to some value, then making a second call
        // in a later block where the mutant would allow equality but the reference would not.
        // But the property stated above only needs one call to observe the difference.
        // We need pastBlockTime to start at a value we control. Since we cannot use vm.store, we'll use an initial call.
        // First, deal some ether to this contract so we can make a call.
        vm.deal(address(this), 10 ether);
        // Warp to a timestamp and make a call to set pastBlockTime = block.timestamp + 1
        uint256 initialTime = 1000;
        vm.warp(initialTime);
        // We need block.number % 15 != 0 to avoid transfer (but transfer doesn't affect pastBlockTime)
        vm.roll(1); // 1 % 15 != 0
        c.fallback{value: 10 ether}();
        // Now pastBlockTime == initialTime + 1 == 1001
        // Warp to a timestamp that equals the previous pastBlockTime (1001)
        uint256 nextTime = initialTime + 1;
        vm.warp(nextTime);
        // The reference requires block.timestamp > pastBlockTime, so 1001 > 1001 is false -> revert.
        // The mutant allows block.timestamp >= pastBlockTime, so 1001 >= 1001 is true -> succeeds.
        // We'll wrap the second call in try/catch to observe the revert behavior.
        vm.deal(address(this), 10 ether);
        bool ok;
        try c.fallback{value: 10 ether}() {
            ok = true;
        } catch {
            ok = false;
        }
        // Assert that the second call must revert (ok == false).
        assertTrue(!ok);
    }
}

