pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 initialWarp, int256 timeSkip) public {
        // Restrict initial timestamp and skip to keep block.timestamp within sensible bounds
        vm.assume(initialWarp >= 1 && initialWarp <= type(uint128).max);
        vm.assume(timeSkip > 0 && timeSkip <= int256(365 days));

        // Fund the caller that will send the exact required msg.value (10 ether)
        address caller = address(0xdead);
        vm.deal(caller, 10 ether);

        // First call at timestamp T = initialWarp
        vm.warp(initialWarp);
        vm.prank(caller);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        require(ok1, "first fallback failed");

        // Capture pastBlockTime after first call
        uint256 firstPast = c.pastBlockTime();

        // Second call at a LATER timestamp: T + timeSkip (strictly greater than first call's block.timestamp)
        uint256 secondTimestamp = initialWarp + uint256(timeSkip);
        vm.warp(secondTimestamp);
        vm.prank(caller);
        (bool ok2, ) = address(c).call{value: 10 ether}("");
        require(ok2, "second fallback failed");

        // Capture pastBlockTime after second call
        uint256 secondPast = c.pastBlockTime();

        // GENERAL RULE: pastBlockTime must never be less than (or equal to) the timestamp of the previous call
        // More precisely: after any sequence of admissible calls, pastBlockTime MUST be > the block.timestamp of the
        // immediately preceding call (which is firstPast - 1 in the reference).
        // The reference ensures secondPast > firstPast - 1 (since block.timestamp > pastBlockTime is enforced).
        // The mutant allows pastBlockTime to be set without that check, so secondPast can equal firstPast - 1 or worse.
        assertTrue(secondPast > firstPast - 1);
    }
}

