pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount1, uint256 amount2, uint256 warp1, uint256 warp2) public {
        vm.deal(address(this), 30 ether);
        amount1 = bound(amount1, 1, 100 ether);
        amount2 = bound(amount2, 1, 100 ether);
        warp1 = bound(warp1, 1, 1000000);
        warp2 = bound(warp2, warp1 + 1, 1000001);
        vm.assume(amount2 != 10 ether);

        vm.warp(warp1);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        require(ok1, "call1 failed");
        uint256 past1 = c.pastBlockTime();

        // drive c with a non-10-ether call at a strictly later timestamp, ensuring pastBlockTime does not change
        vm.warp(warp2);
        (bool ok2,) = address(c).call{value: amount2}("");
        if (amount2 == 10 ether) {
            require(ok2, "call2 failed");
            past1 = c.pastBlockTime();
        }

        // now re-enter at the same timestamp as the first call, which the mutant allows
        vm.warp(warp1);
        vm.roll(block.number + 1); // ensure block.number changes but timestamp reverts
        (bool ok3,) = address(c).call{value: 10 ether}("");
        require(ok3, "call3 failed");

        // after a successful 10-ether call with timestamp = warp1, pastBlockTime must be > warp1
        // reference C enforced block.timestamp > pastBlockTime before update, so it always holds.
        // The mutant deletes that check, so a call at warp1 can succeed, leaving pastBlockTime unchanged or equal to block.timestamp+1,
        // which is not strictly greater than warp1.
        assertTrue(c.pastBlockTime() > warp1);
    }
}

