pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 actorSeed, uint256 value) public {
        // actorSeed generates a pseudorandom actor address; ensure it's not zero.
        address actor = address(uint160(uint256(keccak256(abi.encode(actorSeed))));
        vm.assume(actor != address(0));
        // value must be exactly 10 ether for the require to pass.
        value = bound(value, 10 ether, 10 ether);
        vm.deal(actor, value);

        // Set an initial pastBlockTime in the past so the timestamp check passes.
        // This is part of the admissible setup; we need the call to succeed to observe the state transformation.
        // We cannot set pastBlockTime directly, so we perform a valid "priming" call that sets pastBlockTime = block.timestamp + 1,
        // then warp forward so block.timestamp > pastBlockTime is satisfied for the recorded call.
        // However, the priming call itself may drain the contract if block.number % 15 == 0. To avoid that, we use a separate vm.roll
        // to set block.number to a value not divisible by 15 before the priming call.
        // We'll warp to a known timestamp (say 1000) and set block number accordingly.
        vm.warp(1000);
        vm.roll(1); // 1 % 15 != 0, so priming call won't transfer
        vm.prank(actor);
        c.f{value: 10 ether}(); // priming: sets pastBlockTime = 1000 + 1 = 1001

        // Now warp to a future timestamp and optionally roll to a new block to test the recorded call.
        // For the recorded call, we allow the fuzzer to choose whether block.number % 15 == 0 or not,
        // but we want to observe the state change regardless. We'll set block.number to a small value and
        // warp timestamp enough ahead.
        // The bug only manifests after a successful call where the assignment is missing; so we need at least one more successful call.
        vm.warp(2000); // block.timestamp = 2000 > pastBlockTime (1001)
        // Block number can be any; we'll set it to a fuzzed value between 0 and 100, but ensure it's not zero because division by zero? No issue.
        uint256 blockNum = actorSeed % 101; // 0..100
        vm.roll(blockNum);
        vm.prank(actor);
        // The call requires exactly 10 ether again.
        c.f{value: 10 ether}();

        // After the call, the contract's balance may be zero if block.number % 15 == 0; otherwise it's 20 ether.
        // The rule: if contract balance > 0 (meaning it wasn't drained), then pastBlockTime MUST equal block.timestamp + 1.
        // The buggy version fails to update pastBlockTime, so it stays at the previous value (1001), breaking the rule.
        // We assert exactly that.
        if (address(c).balance > 0) {
            uint256 expected = block.timestamp + 1;
            assertTrue(c.pastBlockTime() == expected);
        } else {
            // If balance == 0, the contract was drained, but the state variable pastBlockTime might still be updated in the correct version.
            // However, the requirement says the difference manifests in pastBlockTime after completion; it doesn't require balance > 0.
            // So we should assert unconditionally that pastBlockTime == block.timestamp + 1 in the reference, and bug fails.
            // To satisfy the universal property, we must not filter by balance. Let's assert directly.
            assertTrue(c.pastBlockTime() == expected);
        }
    }
}

