contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 warp1, uint256 warp2, uint64 roll1, uint64 roll2) public {
        // warp1 and warp2 are future timestamps; we ensure they are ordered and > pastBlockTime (initially 0)
        vm.assume(warp1 > 0);
        vm.assume(warp2 > warp1);
        // rolls are arbitrary; just keep them distinct to avoid accidental 15-divisible coincidences
        vm.assume(roll1 != roll2);

