        vm.deal(address(this), 10 ether);
        c.f{value: 10 ether}();

        // After two successful calls, pastBlockTime must be > block.timestamp (which is warp2)
        // The reference updates it to block.timestamp+1, so it's warp2+1 > warp2.
        // The buggy version omits the update, so pastBlockTime remains at warp1 (if first call didn't update it either)
        // or at most warp1+something < warp2, so pastBlockTime <= warp2, breaking this assertion.
