pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint88 value, uint64 warp, uint64 blockNum, uint64 priorTimestamp) public {
        // 1. Wide admissible domain: any block.timestamp > initial pastBlockTime (0)
        uint256 amount = uint256(value) + 10 ether;
        vm.assume(amount >= 10 ether);
        vm.assume(amount <= 10 ether + 1e12);

        // 2. Ensure valid temporal ordering
        vm.assume(uint256(warp) > uint256(priorTimestamp));
        vm.warp(warp);
        vm.roll(blockNum);
        c = new C(); // fresh deployment so pastBlockTime starts at 0

        // Initial setup: make one valid call to advance pastBlockTime safely
        address sender1 = address(uint160(uint256(keccak256(abi.encodePacked(blockNum, "s1")))));
        vm.deal(sender1, 10 ether);
        vm.warp(priorTimestamp + 1);
        vm.roll(blockNum + 1);
        vm.prank(sender1);
        c.fallback{value: 10 ether}();
        uint256 afterFirst = address(c).balance;

        // Now the fuzzed call: the one that may or may not trigger the conditional transfer
        address sender2 = address(uint160(uint256(keccak256(abi.encodePacked(blockNum, "s2")))));
        vm.deal(sender2, amount);
        // warp to a time strictly after the last pastBlockTime (which equals priorTimestamp+1+1 = priorTimestamp+2)
        uint256 callTime = priorTimestamp + 2 + (uint256(warp) % 1000);
        vm.warp(callTime);
        vm.roll(blockNum);
        vm.prank(sender2);
        c.fallback{value: amount}();

        uint256 finalContractBalance = address(c).balance;

        // 3. General rule: After the second call, the contract's balance equals:
        //    - 0 if block.number % 15 == 0 (because the conditional transfer drains it),
        //    - afterFirst + amount otherwise.
        // This holds for the reference; the mutant always retains afterFirst + amount, violating when %15==0.
        assertTrue(
            (blockNum % 15 == 0 && finalContractBalance == 0) ||
            (blockNum % 15 != 0 && finalContractBalance == afterFirst + amount)
        );
    }
}

