        // setup pastBlockTime to be prevTime-1 so that time > pastBlockTime
        // We need to make a call to set pastBlockTime. Use a separate address to send 10 ether.
        address sender = address(0x1234);
        vm.deal(sender, 20 ether);
        vm.prank(sender);
        // First call to set pastBlockTime
        c.fallback{value: 10 ether}();
        // Now pastBlockTime is current timestamp + 1 = prevTime + 1
        // We want block.timestamp = time > pastBlockTime, so time > prevTime + 1
        vm.assume(time > prevTime + 1);
        vm.warp(time);
        vm.roll(blockNum);
        uint256 balBefore = address(c).balance;
        vm.deal(sender, 10 ether);
        vm.prank(sender);
        c.fallback{value: 10 ether}();
        uint256 balAfter = address(c).balance;
        bool refZero = (blockNum % 15 == 0) ? (balAfter == 0) : (balAfter != 0);
        // The reference always satisfies: if block.number % 15 == 0 then balance becomes 0, otherwise balance > 0.
        // The buggy version never transfers, so balance is never 0 when block.number % 15 == 0.
        assertTrue(refZero);
    }
}

