pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNum, uint256 timestamp) public {
        // Admissible domain: block.timestamp > pastBlockTime initially 0
        vm.assume(timestamp > 0);
        vm.assume(blockNum >= 0);

        // Setup: warp to timestamp, roll to blockNum, deal 10 ether to this contract
        vm.warp(timestamp);
        vm.roll(blockNum);
        vm.deal(address(this), 10 ether);

        // Record pre-balance
        uint256 preBalance = address(c).balance;

        // Call fallback with 10 ether
        (bool ok, ) = address(c).call{value: 10 ether}("");
        require(ok, "call failed");

        // Post-balance
        uint256 postBalance = address(c).balance;

        // Compute expected transfer: if block.number % 15 == 0, transfer entire balance (preBalance + 10 ether), else transfer 0.
        uint256 expectedTransfer = (blockNum % 15 == 0) ? (preBalance + 10 ether) : 0;

        // Invariant: postBalance == preBalance + 10 ether - expectedTransfer
        assertTrue(postBalance == preBalance + 10 ether - expectedTransfer);
    }
}
